INSERT INTO products(item_number,category_id,name,slug,description,specifications,price_agorot,purchase_price_agorot,stock_quantity,active,featured,created_at,updated_at)
SELECT (SELECT COALESCE(MAX(item_number),1000) FROM products)+ROW_NUMBER() OVER(ORDER BY s.source_id),c.id,json_extract(s.data,'$.name'),json_extract(s.data,'$.slug'),json_extract(s.data,'$.name'),NULLIF(json_extract(s.data,'$.specifications'),''),CAST(ROUND(json_extract(s.data,'$.price')*100) AS INTEGER),CAST(ROUND(json_extract(s.data,'$.price')*100) AS INTEGER),json_extract(s.data,'$.stock'),json_extract(s.data,'$.active'),0,1791709399351,1791709399351
FROM _dofesh_oct11_import s JOIN categories c ON c.category_number=json_extract(s.data,'$.categoryNumber')
WHERE NOT EXISTS(SELECT 1 FROM product_keywords k WHERE k.keyword='dofesh-'||s.source_id)
AND NOT EXISTS(SELECT 1 FROM product_suppliers ps WHERE ps.source_product_id=CAST(s.source_id AS TEXT) AND ps.supplier_id=(SELECT id FROM suppliers WHERE supplier_number=9101))
AND NOT EXISTS(SELECT 1 FROM products p WHERE p.slug=json_extract(s.data,'$.slug'));
UPDATE _dofesh_oct11_import SET product_id=(SELECT id FROM products WHERE slug=json_extract(data,'$.slug'));
INSERT OR IGNORE INTO product_keywords(product_id,keyword) SELECT product_id,'dofesh-'||source_id FROM _dofesh_oct11_import WHERE product_id IS NOT NULL;
INSERT OR IGNORE INTO product_suppliers(product_id,supplier_id,source_product_id,source_url,supplier_price_agorot,preferred,created_at,updated_at)
SELECT s.product_id,v.id,CAST(s.source_id AS TEXT),'https://dofesh.ps/?app=product.show.'||s.source_id,CAST(ROUND(json_extract(s.data,'$.price')*100) AS INTEGER),1,1791709399351,1791709399351 FROM _dofesh_oct11_import s JOIN suppliers v ON v.supplier_number=9101 WHERE s.product_id IS NOT NULL;
INSERT INTO product_media(product_id,variant_id,media_type,url,alt_text,sort_order,is_primary,created_at,updated_at)
SELECT s.product_id,NULL,'image',json_extract(s.data,'$.image'),json_extract(s.data,'$.name'),0,1,1791709399351,1791709399351 FROM _dofesh_oct11_import s WHERE s.product_id IS NOT NULL AND json_extract(s.data,'$.placeholder')=0 AND NOT EXISTS(SELECT 1 FROM product_media m WHERE m.product_id=s.product_id AND m.url=json_extract(s.data,'$.image'));
INSERT INTO product_options(product_id,name,display_type,sort_order)
SELECT s.product_id,'الخيار','text',0 FROM _dofesh_oct11_import s WHERE s.product_id IS NOT NULL AND json_array_length(s.data,'$.variants')>0 AND NOT EXISTS(SELECT 1 FROM product_options o WHERE o.product_id=s.product_id);
INSERT INTO product_option_values(option_id,value,sort_order)
SELECT o.id,json_extract(v.value,'$.name'),CAST(v.key AS INTEGER) FROM _dofesh_oct11_import s JOIN product_options o ON o.product_id=s.product_id JOIN json_each(s.data,'$.variants') v WHERE NOT EXISTS(SELECT 1 FROM product_option_values ov WHERE ov.option_id=o.id AND ov.sort_order=CAST(v.key AS INTEGER));
INSERT OR IGNORE INTO product_variants(product_id,sku,price_agorot,purchase_price_agorot,stock_quantity,active,created_at,updated_at)
SELECT s.product_id,'dofesh-oct11-'||s.source_id||'-'||v.key,CAST(ROUND(json_extract(v.value,'$.price')*100) AS INTEGER),CAST(ROUND(json_extract(v.value,'$.price')*100) AS INTEGER),CASE WHEN json_extract(v.value,'$.disabled')=1 THEN 0 ELSE json_extract(s.data,'$.stock') END,1,1791709399351,1791709399351 FROM _dofesh_oct11_import s JOIN json_each(s.data,'$.variants') v WHERE s.product_id IS NOT NULL;
INSERT OR IGNORE INTO variant_option_values(variant_id,option_value_id)
SELECT pv.id,ov.id FROM _dofesh_oct11_import s JOIN json_each(s.data,'$.variants') v JOIN product_variants pv ON pv.sku='dofesh-oct11-'||s.source_id||'-'||v.key JOIN product_options o ON o.product_id=s.product_id JOIN product_option_values ov ON ov.option_id=o.id AND ov.sort_order=CAST(v.key AS INTEGER);
INSERT INTO product_custom_fields(product_id,label,placeholder,max_length,required,sort_order)
SELECT s.product_id,json_extract(f.value,'$.label'),NULL,200,json_extract(f.value,'$.required'),CAST(f.key AS INTEGER) FROM _dofesh_oct11_import s JOIN json_each(s.data,'$.customFields') f WHERE s.product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM product_custom_fields cf WHERE cf.product_id=s.product_id AND cf.label=json_extract(f.value,'$.label'));
CREATE TABLE _dofesh_oct11_validation (total INTEGER CHECK(total=80),published INTEGER CHECK(published=0),stock100 INTEGER CHECK(stock100=42),variants INTEGER CHECK(variants=66),images INTEGER CHECK(images=78),variant_links INTEGER CHECK(variant_links=66));
INSERT INTO _dofesh_oct11_validation SELECT
(SELECT COUNT(*) FROM _dofesh_oct11_import WHERE product_id IS NOT NULL),
(SELECT COUNT(*) FROM products WHERE active=1 AND id IN(SELECT product_id FROM _dofesh_oct11_import)),
(SELECT COUNT(*) FROM products WHERE stock_quantity=100 AND id IN(SELECT product_id FROM _dofesh_oct11_import)),
(SELECT COUNT(*) FROM product_variants WHERE product_id IN(SELECT product_id FROM _dofesh_oct11_import)),
(SELECT COUNT(*) FROM product_media WHERE product_id IN(SELECT product_id FROM _dofesh_oct11_import)),
(SELECT COUNT(*) FROM variant_option_values WHERE variant_id IN(SELECT id FROM product_variants WHERE product_id IN(SELECT product_id FROM _dofesh_oct11_import)));
DROP TABLE _dofesh_oct11_validation;
DROP TABLE _dofesh_oct11_import;

